function evaluateProperty({
    api
}) {
    if (api.state.aisStatus.aisInitialized)
        return 'On';
    else if (api.state.isAISRequested || api.state.aisStatus.aisService || api.state.aisStatus.aisEnabled)
        return 'Pending';
    else
        return 'Off';

}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    if (api.state.aisStatus.aisInitialized)
        return 'positive';
    else if (api.state.isAISRequested || api.state.aisStatus.aisService || api.state.aisStatus.aisEnabled)
        return 'blue';
    else
        return 'gray';

}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    if (api.state.aisStatus.aisInitialized)
        return 'check-outline';
    else if (api.state.isAISRequested || api.state.aisStatus.aisService || api.state.aisStatus.aisEnabled)
        return 'presence-busy-outline';
    else
        return 'ban-outline';

}

/**
